def parse(lines):
    blocks = []
    skip = []
    i = 0
    n = len(lines)
    count = 0
    while i < n:
        s = lines[i]
        if s.startswith('## METRICS CLASS') or s.startswith('## HISTOGRAM'):
            name = 'metrics' if s.startswith('## METRICS') else 'histogram'
            count += 1
            skip.append(i)
            i += 1
            if i < n and lines[i].strip() and not lines[i].startswith('#'):
                hdr = [h.strip() for h in lines[i].split('\t')]
                while hdr and hdr[-1] == '':
                    hdr.pop()
                idx = [i]
                recs = []
                i += 1
                while i < n and lines[i].strip() and not lines[i].startswith('#'):
                    vals = lines[i].split('\t')
                    rec = {}
                    for k, h in enumerate(hdr):
                        rec[h] = vals[k].strip() if k < len(vals) else ''
                    recs.append(rec)
                    idx.append(i)
                    i += 1
                if count > 1 and any(b['name'] == name for b in blocks):
                    name = name + '_' + str(count)
                blocks.append({'name': name, 'kind': 'table', 'lines': idx, 'records': recs})
            continue
        if s.startswith('#'):
            skip.append(i)
        i += 1
    return {'blocks': blocks, 'skip': skip}
